-- 1. regional_cells (non-US sub-national rows)
UPDATE regional_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(rev_p50 * 0.08),
  'payroll_total',          ROUND(rev_p50 * 0.32),
  'cost_of_goods_sold',     ROUND(rev_p50 * 0.12),
  'utilities',              ROUND(rev_p50 * 0.07),
  'marketing_acquisition',  ROUND(rev_p50 * 0.06),
  'insurance_professional', ROUND(rev_p50 * 0.05),
  'equipment_maintenance',  ROUND(rev_p50 * 0.06),
  'regulatory_licensing',   ROUND(rev_p50 * 0.01),
  'refreshed_at',           '2026-05-24',
  'source_note',            'AHLA / STR 2024 industry benchmarks + hospitality cost studies (CBRE 2024). Country revenue captures local price level implicitly.',
  'grade',                  'C'
)
WHERE industry_id = 'hotels_lodging'
  AND rev_p50 IS NOT NULL
  AND rev_p50 > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));

