-- 3. extrapolated_cells (country-level fallback)
UPDATE extrapolated_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(predicted_rev_per_firm * 0.08),
  'payroll_total',          ROUND(predicted_rev_per_firm * 0.32),
  'cost_of_goods_sold',     ROUND(predicted_rev_per_firm * 0.12),
  'utilities',              ROUND(predicted_rev_per_firm * 0.07),
  'marketing_acquisition',  ROUND(predicted_rev_per_firm * 0.06),
  'insurance_professional', ROUND(predicted_rev_per_firm * 0.05),
  'equipment_maintenance',  ROUND(predicted_rev_per_firm * 0.06),
  'regulatory_licensing',   ROUND(predicted_rev_per_firm * 0.01),
  'refreshed_at',           '2026-05-24',
  'source_note',            'AHLA / STR 2024 industry benchmarks + hospitality cost studies (CBRE 2024). Country-level extrapolation; coarser than regional_cells.',
  'grade',                  'D'
)
WHERE industry_id = 'hotels_lodging'
  AND predicted_rev_per_firm IS NOT NULL
  AND predicted_rev_per_firm > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));
